-- P5 中文寫作技巧 5CW1–5CW4：新增 280 題，每單元新增 70 題至 80 題
-- 可安全重複執行，不刪除原有題目。
begin;
do $$
declare missing_codes text;
begin
  select string_agg(code, ', ' order by code) into missing_codes
  from (values ('5CW1'),('5CW2'),('5CW3'),('5CW4')) wanted(code)
  where not exists(select 1 from public.curriculum_nodes n where n.code=wanted.code);
  if missing_codes is not null then raise exception '找不到寫作單元：%',missing_codes; end if;
end $$;
create temporary table tmp_chinese_writing_expansion(
  node_code text not null, category text not null, question_text text not null,
  options jsonb not null, correct_answer jsonb not null, explanation text not null,
  hint text not null, difficulty integer not null
) on commit drop;
do $$
declare bad integer;
begin
  select count(*) into bad from (values ('5CW1',70),('5CW2',70),('5CW3',70),('5CW4',70)) e(code,qty)
  where (select count(*) from tmp_chinese_writing_expansion t where t.node_code=e.code)<>e.qty;
  if bad>0 then raise exception '各寫作單元題數檢查失敗。'; end if;
  if (select count(*) from tmp_chinese_writing_expansion)<>280 then raise exception '總題數不是280。'; end if;
end $$;
select n.id,'multiple_choice',t.question_text,t.options,t.difficulty,'teacher','published'
from tmp_chinese_writing_expansion t join public.curriculum_nodes n on n.code=t.node_code
where not exists(select 1 from public.questions q where q.node_id=n.id and q.question_text=t.question_text);
select q.id,t.correct_answer,t.explanation,t.hint
from tmp_chinese_writing_expansion t join public.curriculum_nodes n on n.code=t.node_code
join public.questions q on q.node_id=n.id and q.question_text=t.question_text
on conflict(question_id) do update set correct_answer=excluded.correct_answer,explanation=excluded.explanation,hint=excluded.hint;
commit;
select n.code,n.title_zh,count(q.id) filter(where q.status='published') as published_questions
from public.curriculum_nodes n left join public.questions q on q.node_id=n.id
where n.code in('5CW1','5CW2','5CW3','5CW4') group by n.code,n.title_zh order by n.code;
